$rule_id = (rule-name().split('.'))[rule-name().split('.').length];


if not applicable_form(rule-name())
	skip
else


$axisExtensibleEnumDict = dict(
                                list(VariableRateAxis, "InvestmentVariableInterestRateTypeExtensibleEnumeration or DebtInstrumentVariableInterestRateTypeExtensibleEnumeration"),
                                )

$all_cubes = filter taxonomy().cubes;

for $cube in $all_cubes
	if $cube.dimensions().concept().name.contains(InitialApplicationPeriodCumulativeEffectTransitionAxis)
		skip
	else
        for $dim in $axisExtensibleEnumDict.keys
            if $cube.dimensions().concept().name.contains($dim)
                    $domain = navigate dimensions dimension-domain descendants from $dim drs-role $cube.drs-role returns set target-name;
                    if count(navigate dimensions descendants from $domain drs-role $cube.drs-role cube $cube.cube-concept()) == 1
                        $PrimaryConcepts = list({@cube = $cube @$dim = *});
                        $count_values = count($PrimaryConcepts);
                        if $count_values == 1 and (not exists({@concept = $PrimaryConcepts[1].concept @$dim = none}))
                            $PrimaryConcept = $PrimaryConcepts[1]
                            true
                        else
                            false
                    else
                        skip
            else
                    skip


